<?php namespace App\Services;
use App\Helpers\HttpException; use App\Models\{Attendance,Student,Subject,Teacher};
final class AttendanceService { public function __construct(private \PDO $db) {} public function create(int $userId,array $in):array {$teacher=(new Teacher($this->db))->byUser($userId);$subject=(int)($in['subject_id']??0);$minutes=(int)($in['minutes']??10);$title=trim((string)($in['title']??'Attendance session'));if(!$teacher||!(new Subject($this->db))->exists($subject))throw new HttpException('A valid subject is required.',422);if($minutes<1||$minutes>240)throw new HttpException('QR expiry must be between 1 and 240 minutes.',422);$this->db->beginTransaction();try{$this->db->prepare('UPDATE qr_codes q JOIN attendance_sessions s ON s.id=q.session_id SET q.active=0 WHERE s.teacher_id=? AND q.active=1')->execute([$teacher['id']]);$this->db->prepare('UPDATE attendance_sessions SET active=0 WHERE teacher_id=? AND active=1')->execute([$teacher['id']]);$this->db->prepare('INSERT INTO attendance_sessions(teacher_id,subject_id,title,expires_at) VALUES(?,?,?,DATE_ADD(NOW(),INTERVAL ? MINUTE))')->execute([$teacher['id'],$subject,$title?:'Attendance session',$minutes]);$session=(int)$this->db->lastInsertId();$token=bin2hex(random_bytes(24));$this->db->prepare('INSERT INTO qr_codes(session_id,token,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL ? MINUTE))')->execute([$session,$token,$minutes]);$this->db->commit();return ['session_id'=>$session,'token'=>$token,'expires_at'=>date(DATE_ATOM,time()+$minutes*60)];}catch(\Throwable $e){$this->db->rollBack();throw $e;}} public function scan(int $userId,string $token):array {$student=(new Student($this->db))->byUser($userId);$q=$this->db->prepare('SELECT q.session_id FROM qr_codes q JOIN attendance_sessions s ON s.id=q.session_id WHERE q.token=? AND q.active=1 AND s.active=1 AND q.expires_at>NOW() AND s.expires_at>NOW()');$q->execute([$token]);$qr=$q->fetch();if(!$qr)throw new HttpException('Invalid or expired QR code.',422);try{(new Attendance($this->db))->record((int)$qr['session_id'],(int)$student['id']);return ['message'=>'Attendance recorded.'];}catch(\PDOException $e){if($e->getCode()==='23000')throw new HttpException('Attendance has already been recorded.',422);throw $e;}} public function live(int $userId):array {$teacher=(new Teacher($this->db))->byUser($userId);$s=$this->db->prepare('SELECT a.id,a.title,a.expires_at,sub.name subject FROM attendance_sessions a JOIN subjects sub ON sub.id=a.subject_id WHERE a.teacher_id=? AND a.active=1 AND a.expires_at>NOW() ORDER BY a.id DESC LIMIT 1');$s->execute([$teacher['id']]);$session=$s->fetch();return $session?['session'=>$session,'attendance'=>(new Attendance($this->db))->live((int)$session['id'])]:['session'=>null,'attendance'=>[]];} public function manual(int $userId,array $in):array {$teacher=(new Teacher($this->db))->byUser($userId);$session=(int)($in['session_id']??0);$student=(int)($in['student_id']??0);$check=$this->db->prepare('SELECT id FROM attendance_sessions WHERE id=? AND teacher_id=?');$check->execute([$session,$teacher['id']]);if(!$check->fetch())throw new HttpException('Attendance session not found.',404);try{(new Attendance($this->db))->record($session,$student,($in['status']??'present'));return ['message'=>'Attendance recorded manually.'];}catch(\PDOException $e){throw new HttpException('Attendance has already been recorded.',422);}} }
